HorizontalAdd(v256i16,v256i16) @ref(Vector256.Create((short)($0.GetElement(0) + $0.GetElement(1)), (short)($0.GetElement(2) + $0.GetElement(3)), (short)($0.GetElement(4) + $0.GetElement(5)), (short)($0.GetElement(6) + $0.GetElement(7)), (short)($1.GetElement(0) + $1.GetElement(1)), (short)($1.GetElement(2) + $1.GetElement(3)), (short)($1.GetElement(4) + $1.GetElement(5)), (short)($1.GetElement(6) + $1.GetElement(7)), (short)($0.GetElement(8) + $0.GetElement(9)), (short)($0.GetElement(10) + $0.GetElement(11)), (short)($0.GetElement(12) + $0.GetElement(13)), (short)($0.GetElement(14) + $0.GetElement(15)), (short)($1.GetElement(8) + $1.GetElement(9)), (short)($1.GetElement(10) + $1.GetElement(11)), (short)($1.GetElement(12) + $1.GetElement(13)), (short)($1.GetElement(14) + $1.GetElement(15)))) = _mm256_hadd_epi16($0, $1)
HorizontalAdd(v256i32,v256i32) @ref(Vector256.Create($0.GetElement(0) + $0.GetElement(1), $0.GetElement(2) + $0.GetElement(3), $1.GetElement(0) + $1.GetElement(1), $1.GetElement(2) + $1.GetElement(3), $0.GetElement(4) + $0.GetElement(5), $0.GetElement(6) + $0.GetElement(7), $1.GetElement(4) + $1.GetElement(5), $1.GetElement(6) + $1.GetElement(7))) = _mm256_hadd_epi32($0, $1)
